const EventEmitter = require("events");

class Stock extends EventEmitter {
  constructor(quantites) {
    super();
    this.quantites = { ...quantites };
  }

  retirer(produit, n) {
    const disponible = this.quantites[produit] || 0;
    if (n > disponible) throw new Error("stock insuffisant");
    this.quantites[produit] = disponible - n;
    if (this.quantites[produit] === 0) this.emit("rupture", produit);
  }
}

